<?php declare(strict_types=1); ?>
<div class="module-toolbar"><div><p class="module-intro">Depo, ürün, işlem türü ve tarih aralığına göre stok hareketlerini izleyin.</p></div><a class="btn secondary action-link" href="index.php?page=warehouses">← Depolar</a></div>
<section class="panel"><div class="panel-head"><h3>Hareket filtreleri</h3></div><form method="get"><input type="hidden" name="page" value="warehouses"><input type="hidden" name="action" value="movements"><div class="customer-fields"><label>Depo<select name="warehouse_id"><option value="0">Tüm depolar</option><?php foreach($warehouses as $w): ?><option value="<?= (int)$w['id'] ?>" <?= $warehouseId===(int)$w['id']?'selected':'' ?>><?= kd_e($w['name']) ?></option><?php endforeach; ?></select></label><label>Ürün ID<input type="number" min="1" name="product_id" value="<?= $productId?:'' ?>"></label><label>Hareket türü<select name="movement_type"><option value="">Tüm türler</option><?php foreach($allowedTypes as $kind): ?><option value="<?= kd_e($kind) ?>" <?= $type===$kind?'selected':'' ?>><?= kd_e($kind) ?></option><?php endforeach; ?></select></label><label>Başlangıç<input type="date" name="from" value="<?= kd_e($from) ?>"></label><label>Bitiş<input type="date" name="to" value="<?= kd_e($to) ?>"></label></div><div class="form-actions"><button class="btn primary">Filtrele</button></div></form></section>
<section class="panel"><div class="panel-head"><h3>Stok hareketleri</h3><span class="result-count">En son 300 kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Depo</th><th>Ürün</th><th>Tür</th><th>Miktar</th><th>Önce</th><th>Sonra</th><th>Açıklama</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?= kd_e($m['created_at']) ?></td><td><?= kd_e($m['warehouse_name']?:'—') ?></td><td><?= kd_e($m['product_name']) ?> (<?= kd_e($m['sku']?:'—') ?>)</td><td><?= kd_e($m['movement_type']) ?></td><td><?= number_format((float)$m['quantity'],3,',','.') ?></td><td><?= number_format((float)$m['before_quantity'],3,',','.') ?></td><td><?= number_format((float)$m['after_quantity'],3,',','.') ?></td><td><?= kd_e($m['note']?:'—') ?></td></tr><?php endforeach; ?><?php if(!$movements): ?><tr><td colspan="8" class="empty-state">Seçilen filtrelerde hareket bulunamadı.</td></tr><?php endif; ?></tbody></table></div></section>
